SELECT ASM.AR_SUMMARY_MANAGE_NO, HRE.EMPID, HRE.LOCAL_NAME, GET_DEPT_NAME(HRE.DEPTNO, #{lang, jdbcType=VARCHAR}) DEPTNAME, GET_GLOBAL_NAME(HRE.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) POST_GRADE, TO_CHAR(HRE.DATE_STARTED, 'DD/MM/YYYY') DATE_STARTED, ASM.ITEM_NO, GET_GLOBAL_NAME(ASM.ITEM_NO, #{lang, jdbcType=VARCHAR}) ITEM_NAME, TO_CHAR(PPS.AR_START_DATE, 'DD/MM/YYYY') AR_START_DATE, ASM.CAL_VALUE, ASM.FINAL_VALUE, ASM.REMARK, GET_EMP_LOCAL_NAME(ASM.UPDATED_BY, #{cpnyId, jdbcType=VARCHAR}) || ' ' || ASM.UPDATED_IP UPDATED_BY, TO_CHAR(ASM.UPDATE_DATE, 'DD/MM/YYYY HH24:MI') UPDATE_DATE FROM AR_SUMMARY_MANAGE_HAE ASM, HR_EMPLOYEE HRE, PA_PAY_SCHEDULE PPS WHERE ASM.PERSON_ID = HRE.PERSON_ID AND ASM.PAY_SCHEDULE_NO = PPS.PAY_SCHEDULE_NO AND ASM.PAY_SCHEDULE_NO = #{payScheduleNo, jdbcType=VARCHAR}
AND ASM.ITEM_NO IN
#{itemNo, jdbcType=VARCHAR}
AND ASM.FINAL_VALUE IS NOT NULL
ORDER BY HRE.EMPID, ASM.AR_SUMMARY_MANAGE_NO
